{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "department",
  "per_column": [
    {
      "name": "reason_category",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "A semantic grouping of reason_for_visit that lies outside the focus. Clinical reason categories (Cardiovascular, Skin/Dermatology, Injury/Trauma) plausibly carry strong predictive signal about which department a visit is routed to, without restating or leaking department itself."
    },
    {
      "name": "departments_for_reason_category",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "This column is constructed from the department values themselves (the set of departments observed for each reason category). It is a deterministic aggregate over the focus variable, so it directly encodes/leaks the outcome and cannot serve as a legitimate predictor available before the department is known."
    },
    {
      "name": "reason_category_dept_count",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "The count of distinct departments per reason category is derived entirely from the department column. It is a deterministic function of the focus variable's distribution, encoding outcome information and constituting leakage rather than an independent predictive feature."
    }
  ],
  "n_predictors": 1,
  "predictive_utility": 0.35,
  "rationale": "Only reason_category is a legitimate outside-the-focus predictor and it does carry real signal for mapping visit reasons to departments. The other two columns are aggregations derived from the department variable itself (its set and its cardinality per reason category), which leak the outcome and would inflate model performance while being unavailable at prediction time. As a set, the genuine predictive leverage beyond the original reason_for_visit column is modest, since reason_category is largely a coarser view of information already present."
}

